type Celsius = Float64;

fn convert_to_fahrenheit(c: Celsius) -> Float64 {
  c * 9.0 / 5.0 + 32.0
}

fn main() -> Int {
  let temp: Celsius = 25.0;
  let f = convert_to_fahrenheit(temp);
  return 0;
}
